99			Use:   "show [<trail>]",
100			Short: "Show a trail",
101			Long: `Show a trail.
102	
103	If <trail> is omitted, shows the trail for the current branch. Otherwise,
104	<trail> may be a trail number, id, or branch in the current repo.`,
105			Args: cobra.MaximumNArgs(1),
106			RunE: func(cmd *cobra.Command, args []string) error {
107				selector := ""
108				if len(args) == 1 {
109					selector = args[0]
110				}
111				return runTrailShow(cmd.Context(), cmd.OutOrStdout(), cmd.ErrOrStderr(), trailInsecureHTTP(cmd), selector)
112			},
113		}
